    if re.search(r'\buntil \[|\buntil grep|progress\.log|batch1\.log|batch2\.log|q2\.log|heavy\.log|pa\.txt|pu\.txt|\bsleep \d+;\s*cat|ps aux|ps -eo|\buptime\b(?!.*git log)', cmd) and 'git commit' not in cmd:
