        return 'COORD_RECORD'

    # reports/probes
    if re.search(r'rung-exclusion-remainder|REPORT\.md|SKEPTIC\.md|perf-probes/nat|zero\.md|zElig|exclusion-trace\.md|library-scalar-extension-review-probes|explorations/reviews/[a-z-]+ways\.md|explorations/reviews.*head -1|coordinator-context-2026', text):
        return 'REPORTS_PROBES'

    # specification
    if re.search(r'Specification/|Specification-1\.0-frozen|Documentation/Specification|Papers/|pdftotext|\.tex\b|\.tick\b', text):
        return 'SPEC'

    # checker/interpreter source
    if re.search(r'TypeHierarchyChecker\.scala|StaticChecker\.java|ExportChecker\.scala|FType\.java|FTypeTrait\.java|BuildEnvironments\.java|ProjectProperties\.java|bin/fortress\b|bin/fortress_home|default_repository/configuration', text):
        return 'CHECKER_SRC'

    # library source
    if re.search(r'FortressLibrary\.fsi|FortressLibrary\.fss|FortressBuiltin\.fsi|CompilerAlgebra\.fsi|List\.fsi|Library/\*\.fs', text):
        return 'LIBRARY_SRC'

