    if re.search(r'make-libs\.py|shadow-thc\.py|shadow-walk407\.py|cat > count\.sh|cat > ctests\.sh|cat > distance\.sh|cat > walk\.sh|cat > probe\.sh|cat > mg\.sh|cat > tests\.sh|cat > probe-all\.sh|cat > compare-mg\.sh|cat > collect\.sh|cat > errlist\.py|cat > compare-tests\.py|scala\.tools\.nsc\.Main|javac -nowarn.*-d \$W|chmod \+x \.\./probe\.sh|chmod \+x walk\.sh|chmod \+x distance\.sh|chmod \+x ctests\.sh', cmd):
        return 'BUILD'

    # running checker (count/distance/ctests stage invocations)
    if re.search(r'count\.sh \$W/cc|bash \$D/count\.sh|distance\.sh \$W/ds|bash \$D/distance\.sh|ctests\.sh \$W/ct|bash \$D/ctests\.sh|errors-.*\.txt|batch1\.log|table-\$v\.txt|comm -13 \$W|diff \$W/errors|thc-classes.*count', cmd):
        return 'RUN_CHECKER'

    # walk / microgpt / interpreter tests
    if re.search(r'walk\.sh \$W/wk|bash \$D/walk\.sh|bash \$D/mg\.sh|bash \$D/tests\.sh|bash \$D/probe\.sh|bash \$D/probe-all\.sh|walk-c4-|walk-apl-|MicroGptFlatCheck|MicroGptAplCheck', cmd):
        return 'WALK_RUN'

    return 'OTHER'

fam = {}
for c in calls:
    f = classify(c)
    rid = c['id']
    rts = results.get(rid)
    dur = None
    if rts:
        dur = (parse(rts) - parse(c['ts'])).total_seconds()
    fam.setdefault(f, []).append((c['idx'], c['ts'], dur, c['name']))

for f, items in sorted(fam.items(), key=lambda x:-len(x[1])):
    total = sum(d for _,_,d,_ in items if d is not None)
    n = len(items)
    tmin = min(i[1] for i in items)
    tmax = max(i[1] for i in items)
    print(f"{f}: n={n} sum_dur={total/60:.1f}min first={tmin} last={tmax}")
print()
print("OTHER calls detail:")
for idx,ts,dur,name in fam.get('OTHER',[]):
    print(idx, ts, name)
PYEOF

